    public override Dictionary<string, object> parseMarket(object market)
    {
        string? type = this.safeString(market, "instrument_type");
        string? marketType = null;
        bool spot = false;
        bool margin = true;
        bool swap = false;
        bool option = false;
        bool? linear = null;
        bool? inverse = null;
        string? baseId = this.safeString(market, "base_currency");
        string? quoteId = this.safeString(market, "quote_currency");
        string? bs = this.safeCurrencyCode(baseId);
        string? quote = this.safeCurrencyCode(quoteId);
        if (((bs == null)) || ((quote == null)))
        {
            return ccxt.BaseExchange.ToDict(null);
        }
        string? marketId = this.safeString(market, "instrument_name");
        string symbol = ((bs + "/") + quote);
        string? settleId = null;
        string? settle = null;
        Int64? expiry = null;
        Int64? strike = null;
        string? optionType = null;
        string? optionLetter = null;
        if (type == "erc20")
        {
            spot = true;
            marketType = "spot";
        } else if (type == "perp")
        {
            margin = false;
            settleId = "USDC";
            settle = this.safeCurrencyCode(settleId);
            symbol = ((((bs + "/") + quote) + ":") + settle);
            swap = true;
            linear = true;
            inverse = false;
            marketType = "swap";
        } else if (type == "option")
        {
            settleId = "USDC";
            settle = this.safeCurrencyCode(settleId);
            margin = false;
            option = true;
            marketType = "option";
            IDictionary<string, object> optionDetails = this.safeDict(market, "option_details");
            expiry = this.safeTimestamp(optionDetails, "expiry");
            strike = this.safeInteger(optionDetails, "strike");
            optionLetter = this.safeString(optionDetails, "option_type");
            symbol = ((((((((((bs + "/") + quote) + ":") + settle) + "-") + this.yymmdd(expiry)) + "-") + this.numberToString(strike)) + "-") + optionLetter);
            if (optionLetter == "P")
            {
                optionType = "put";
            } else
            {
                optionType = "call";
            }
            linear = true;
            inverse = false;
        }
        int? contractSize = spot ? null : 1;
        bool isContract = (swap || option);
        return this.safeMarketStructure(new Dictionary<string, object>() {
            { "id", marketId },
            { "symbol", symbol },
            { "base", bs },
            { "quote", quote },
            { "settle", settle },
            { "baseId", baseId },
            { "quoteId", quoteId },
            { "settleId", settleId },
            { "type", marketType },
            { "spot", spot },
            { "margin", margin },
            { "swap", swap },
            { "future", false },
            { "option", option },
            { "active", this.safeBool(market, "is_active") },
            { "contract", isContract },
            { "linear", linear },
            { "inverse", inverse },
            { "contractSize", contractSize },
            { "expiry", expiry },
            { "expiryDatetime", this.iso8601(expiry) },
            { "taker", this.safeNumber(market, "taker_fee_rate") },
            { "maker", this.safeNumber(market, "maker_fee_rate") },
            { "strike", strike },
            { "optionType", optionType },
            { "precision", new Dictionary<string, object>() {
                { "amount", this.safeNumber(market, "amount_step") },
                { "price", this.safeNumber(market, "tick_size") },
            } },
            { "limits", new Dictionary<string, object>() {
                { "leverage", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "amount", new Dictionary<string, object>() {
                    { "min", this.safeNumber(market, "minimum_amount") },
                    { "max", this.safeNumber(market, "maximum_amount") },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
            } },
            { "created", null },
            { "info", market },
        });
    }

